mited by French climbers Maurice Herzog and Louis Lachenal in 1950.","alternatives":[{"id":"01a2190a-ae51-7404-b8f2-1a1f594b456e","description":"Annapurna","correct_answer":true},{"id":"01a2190a-ae51-7cea-9fc3-3a7439689fd6","description":"Mount Everest","correct_answer":false},{"id":"01a2190a-ae51-7060-bde4-cd2e42bbdb08","description":"K2","correct_answer":false},{"id":"01a2190a-ae51-7a27-956f-024a1b043d8f","description":"Kangchenjunga","correct_answer":false}]}]', true);

